 INSERT dbo.Keily_Subasta_Auctions (VehicleID,BasePrice,StartAt,EndAt,Status) SELECT VehicleID,18500,DATEADD(day,-1,SYSUTCDATETIME()),DATEADD(day,5,SYSUTCDATETIME()),'ACTIVE' FROM dbo.Keily_Subasta_Vehicles WHERE Brand=N'Toyota';
 INSERT dbo.Keily_Subasta_Auctions (VehicleID,BasePrice,StartAt,EndAt,Status) SELECT VehicleID,12600,DATEADD(day,-2,SYSUTCDATETIME()),DATEADD(day,2,SYSUTCDATETIME()),'ACTIVE' FROM dbo.Keily_Subasta_Vehicles WHERE Brand=N'BMW';
 INSERT dbo.Keily_Subasta_Auctions (VehicleID,BasePrice,StartAt,EndAt,Status) SELECT VehicleID,5400,DATEADD(day,-10,SYSUTCDATETIME()),DATEADD(day,-1,SYSUTCDATETIME()),'ENDED' FROM dbo.Keily_Subasta_Vehicles WHERE Brand=N'Ford';
 INSERT dbo.Keily_Subasta_Auctions (VehicleID,BasePrice,StartAt,EndAt,Status) SELECT VehicleID,22000,DATEADD(day,3,SYSUTCDATETIME()),DATEADD(day,10,SYSUTCDATETIME()),'SCHEDULED' FROM dbo.Keily_Subasta_Vehicles WHERE Brand=N'Mazda';
 INSERT dbo.Keily_Subasta_Bids (AuctionID,BidderUserID,Amount) SELECT a.AuctionID,@Bruno,19000 FROM dbo.Keily_Subasta_Auctions a JOIN dbo.Keily_Subasta_Vehicles v ON v.VehicleID=a.VehicleID WHERE v.Brand=N'Toyota';
 INSERT dbo.Keily_Subasta_Bids (AuctionID,BidderUserID,Amount) SELECT a.AuctionID,@Carla,19300 FROM dbo.Keily_Subasta_Auctions a JOIN dbo.Keily_Subasta_Vehicles v ON v.VehicleID=a.VehicleID WHERE v.Brand=N'Toyota';
 INSERT dbo.Keily_Subasta_Bids (AuctionID,BidderUserID,Amount) SELECT a.AuctionID,@Ana,13100 FROM dbo.Keily_Subasta_Auctions a JOIN dbo.Keily_Subasta_Vehicles v ON v.VehicleID=a.VehicleID WHERE v.Brand=N'BMW';
